with parsed as (select id, service, host, log_ts, latency_ms, status_code, context, cast((status_code & 1) != 0 as int) as has_fault, context['region'] as region from app_logs) select id, host, has_fault, lead(latency_ms, 2) over (partition by month(log_ts), host order by latency_ms, id) as next_latency_ms, max(has_fault) over (partition by host, service order by cast(log_ts as bigint) range between 900 preceding and current row) as has_fault_max_15m from parsed;
